code_snippets.parse_list:
def parse_list(self, response):
    items = response.css('ul li')
    for item in items:
        detail_url = item.css('a::attr(href)').get()
        if detail_url:
            yield response.follow(detail_url, self.parse_detail)

code_snippets.parse_detail:
def parse_detail(self, response):
    yield {
        'title': response.css('h1.page-title::text').get(),
        'authors': response.css('.field--name-field-authors .field__item::text').getall(),
        'abstract': response.css('.field--name-field-abstract .field__item::text').get(),
        'publication_date': response.css('.field--name-field-publication-date .field__item::text').get(),
        'pdf_link': response.urljoin(response.css('a[href$=".pdf"]::attr(href)').get() or ''),
        'supplementary_materials': [response.urljoin(url) for url in response.css('a.supplementary-material::attr(href)').getall()]
    }
